function debounce(fn, waitMs, { immediate = false } = {}) {
  let timer = null;

  const debounced = function(...args) {
    const callNow = immediate && !timer;

    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (!immediate) {
        fn.apply(this, args);
      }
    }, waitMs);

    if (callNow) {
      fn.apply(this, args);
    }
  };

  debounced.cancel = function() {
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
  };

  return debounced;
}

