function diff(oldNode, newNode) {
  if (!newNode) return { type: 'REMOVE' };
  if (!oldNode) return { type: 'CREATE', node: newNode };
  if (oldNode.type !== newNode.type) return { type: 'REPLACE', node: newNode };

  const propPatches = {};
  const oldProps = oldNode.props || {};
  const newProps = newNode.props || {};

  for (const [k, v] of Object.entries(newProps)) {
    if (oldProps[k] !== v) propPatches[k] = v;
  }
  for (const k of Object.keys(oldProps)) {
    if (!(k in newProps)) propPatches[k] = undefined;
  }

  const childPatches = [];
  const maxLen = Math.max((oldNode.children || []).length, (newNode.children || []).length);
  for (let i = 0; i < maxLen; i++) {
    const patch = diff((oldNode.children || [])[i], (newNode.children || [])[i]);
    if (patch) childPatches.push({ index: i, patch });
  }

  return {
    type: 'UPDATE',
    props: Object.keys(propPatches).length > 0 ? propPatches : null,
    children: childPatches
  };
}

module.exports = { diff };

