function validateSchema(payload, schema) {
  const errors = [];
  const data = payload || {};

  for (const [key, rules] of Object.entries(schema)) {
    const val = data[key];
    const exists = val !== undefined && val !== null;

    if (rules.required && !exists) {
      errors.push(`Field ${key} is required`);
      continue;
    }
    if (!exists) continue;

    let actualType = typeof val;
    if (Array.isArray(val)) actualType = 'array';
    if (actualType !== rules.type) {
      errors.push(`Field ${key} must be of type ${rules.type}`);
      continue;
    }

    if (rules.type === 'string' && rules.min !== undefined && val.length < rules.min) {
      errors.push(`Field ${key} must have minimum length ${rules.min}`);
    }
    if (rules.type === 'number' && rules.min !== undefined && val < rules.min) {
      errors.push(`Field ${key} must be at least ${rules.min}`);
    }
  }

  return { valid: errors.length === 0, errors };
}

module.exports = { validateSchema };

