package com.example.security;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import java.io.IOException;
import java.util.Collections;

@Component
public class JwtAuthFilter extends OncePerRequestFilter {
    private final JwtTokenValidator validator = new JwtTokenValidator();

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain) throws ServletException, IOException {
        String authHeader = request.getHeader("Authorization");
        if (authHeader != null && authHeader.startsWith("Bearer ")) {
            String token = authHeader.substring(7).trim();
            if (validator.isValid(token)) {
                String username = validator.getUsername(token);
                String role = validator.getRole(token);
                UsernamePasswordAuthenticationToken auth = new UsernamePasswordAuthenticationToken(
                        username,
                        null,
                        Collections.singletonList(new SimpleGrantedAuthority(role))
                );
                SecurityContextHolder.getContext().setAuthentication(auth);
            }
        }
        filterChain.doFilter(request, response);
    }
}

import re
from pydantic import BaseModel, field_validator

class StudentRegistration(BaseModel):
    fullName: str
    email: str
    phone: str

    @field_validator("fullName")
    @classmethod
    def sanitize_name(cls, v: str) -> str:
        cleaned = re.sub(r"<[^>]*>", "", v).strip()
        if not cleaned:
            raise ValueError("Full name cannot be blank or pure HTML tags")
        return cleaned

    @field_validator("email")
    @classmethod
    def normalize_email(cls, v: str) -> str:
        cleaned = v.strip().lower()
        if "@" not in cleaned or "." not in cleaned:
            raise ValueError("Invalid email format")
        return cleaned

    @field_validator("phone")
    @classmethod
    def normalize_phone(cls, v: str) -> str:
        digits = re.sub(r"[^0-9+]", "", v.strip())
        if not digits.startswith("+"):
            digits = "+91" + digits  # Default country code
        raw_digits = digits.replace("+", "")
        if len(raw_digits) < 10 or len(raw_digits) > 15:
            raise ValueError("Phone must contain between 10 and 15 digits")
        return digits
